#define F_SIZE(field) FIELD_OFFSET(DEVMODEW, field) + sizeof(dm->field)
        { DM_ORIENTATION, F_SIZE(dmOrientation) },
        { DM_PAPERSIZE, F_SIZE(dmPaperSize) },
        { DM_PAPERLENGTH, F_SIZE(dmPaperLength) },
        { DM_PAPERWIDTH, F_SIZE(dmPaperWidth) },
