        if (!ControlService(service, SERVICE_CONTROL_REENUMERATE_ROOT_DEVICES, &status))
            ERR("Failed to control service %s, error %lu.\n", debugstr_w(service_name), GetLastError());
        CloseServiceHandle(service);
