    ret = create_printers_reg_key( system_printers_key, &printers_key );
    if (ret) return ret;

    TRACE("printer->name: %s\n", debugstr_w(printer->name));

    if (printer->name) {

        ret = RegOpenKeyW( printers_key, printer->name, &hkeyPrinter );
        if (ret)
        {
