    }
    *pcbNeeded = nSize;
    ret = RegQueryValueExA( printer->name ? hkeySubkey : printers_key, pValueName,
                            0, pType, pData, pcbNeeded );

    if (!ret && !pData) ret = ERROR_MORE_DATA;

    RegCloseKey(hkeySubkey);
    RegCloseKey(hkeyPrinter);
    RegCloseKey( printers_key );

    TRACE("--> %ld\n", ret);
