    D3DXMatrixIdentity(pout);
    pout->m[0][0] = 1.0f / (aspect * tanf(fovy/2.0f));
    pout->m[1][1] = 1.0f / tanf(fovy/2.0f);
    pout->m[2][2] = zf / (zf - zn);
    pout->m[2][3] = 1.0f;
